// guardedOrganizationRepository keeps Organization's references whole; see guard.
type guardedOrganizationRepository struct {
	OrganizationRepository
	refs *repox.References
}

func (g *guardedOrganizationRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "directory.acme.example/Organization", name)
	if err != nil {
		return err
	}
	if err := g.OrganizationRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, false)
	return nil
}

// resolveOrganizationReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveOrganizationReferences(ctx context.Context, refs *repox.References, m *directoryv1.Organization, paths []string) error {
	return nil
}

// queueOrganizationReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueOrganizationReferences(u *repox.Unit, m *directoryv1.Organization, paths []string) {
}

// queueOrganizationDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueOrganizationDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "directory.acme.example/Organization", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

// queueOrganizationPurge makes u ask name's referrers before it commits; the
// purge it queues keeps the row when *keep is true.
func queueOrganizationPurge(u *repox.Unit, name string) (keep *bool) {
	keep = new(bool)
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error {
			*keep = refs.KeepOnPurge(ctx, "directory.acme.example/Organization", name)
			return nil
		})
	}
	return keep
}

